import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Propuesta de Innovación Curricular: Programación II (2026)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Programacion_II/Propuesta_Contenido_Programatico_2026.md","filePath":"materias/Programacion_II/Propuesta_Contenido_Programatico_2026.md"}'),r={name:"materias/Programacion_II/Propuesta_Contenido_Programatico_2026.md"};function s(t,e,d,l,c,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="propuesta-de-innovacion-curricular-programacion-ii-2026" tabindex="-1">Propuesta de Innovación Curricular: Programación II (2026) <a class="header-anchor" href="#propuesta-de-innovacion-curricular-programacion-ii-2026" aria-label="Permalink to &quot;Propuesta de Innovación Curricular: Programación II (2026)&quot;">​</a></h1><h3 id="campo-de-investigacion-informatica" tabindex="-1"><strong>Campo de Investigación:</strong> Informática <a class="header-anchor" href="#campo-de-investigacion-informatica" aria-label="Permalink to &quot;**Campo de Investigación:** Informática&quot;">​</a></h3><h3 id="area-de-investigacion-informatica-aplicada" tabindex="-1"><strong>Área de Investigación:</strong> Informática Aplicada <a class="header-anchor" href="#area-de-investigacion-informatica-aplicada" aria-label="Permalink to &quot;**Área de Investigación:** Informática Aplicada&quot;">​</a></h3><h3 id="linea-de-investigacion-principal-desarrollo-de-aplicaciones" tabindex="-1"><strong>Línea de Investigación Principal:</strong> Desarrollo de Aplicaciones <a class="header-anchor" href="#linea-de-investigacion-principal-desarrollo-de-aplicaciones" aria-label="Permalink to &quot;**Línea de Investigación Principal:** Desarrollo de Aplicaciones&quot;">​</a></h3><h3 id="linea-de-investigacion-secundaria-ingenieria-del-software" tabindex="-1"><strong>Línea de Investigación Secundaria:</strong> Ingeniería del Software <a class="header-anchor" href="#linea-de-investigacion-secundaria-ingenieria-del-software" aria-label="Permalink to &quot;**Línea de Investigación Secundaria:** Ingeniería del Software&quot;">​</a></h3><h3 id="enfoque-profesionalizacion-del-desarrollo-mediante-arquitectura-de-capas-persistencia-y-despliegue-real" tabindex="-1"><strong>Enfoque:</strong> Profesionalización del Desarrollo mediante Arquitectura de Capas, Persistencia y Despliegue Real <a class="header-anchor" href="#enfoque-profesionalizacion-del-desarrollo-mediante-arquitectura-de-capas-persistencia-y-despliegue-real" aria-label="Permalink to &quot;**Enfoque:** Profesionalización del Desarrollo mediante Arquitectura de Capas, Persistencia y Despliegue Real&quot;">​</a></h3><h2 id="justificacion-pedagogica-e-investigativa" tabindex="-1">Justificación Pedagógica e Investigativa <a class="header-anchor" href="#justificacion-pedagogica-e-investigativa" aria-label="Permalink to &quot;Justificación Pedagógica e Investigativa&quot;">​</a></h2><h3 id="vinculacion-con-las-lineas-de-investigacion-del-pnfi" tabindex="-1">Vinculación con las Líneas de Investigación del PNFI <a class="header-anchor" href="#vinculacion-con-las-lineas-de-investigacion-del-pnfi" aria-label="Permalink to &quot;Vinculación con las Líneas de Investigación del PNFI&quot;">​</a></h3><p>De acuerdo con la estructura jerárquica de investigación del Programa Nacional de Formación en Informática (PNFI), las líneas de investigación constituyen grupos de proyectos y planes de trabajo organizados de forma sistemática, cuyo propósito es orientar la investigación científica dentro de los Proyectos Sociotecnológicos (PST) para dar respuestas cognitivas y socialmente pertinentes a los problemas de las comunidades.</p><p>La presente propuesta se inscribe de manera principal en la línea de <strong>Desarrollo de Aplicaciones</strong>, por cuanto su contenido aborda directamente los siguientes programas (dimensiones operativas) de dicha línea:</p><ul><li><strong>Aplicaciones cliente-servidor:</strong> Las unidades de Arquitectura de Sistemas Web (Unidad 7), Servidores Web con Express.js (Unidad 10) y el Proyecto Final Full-Stack (Unidad 14) forman al estudiante en el diseño e implementación de &quot;sistemas distribuidos que separan responsabilidades entre clientes que solicitan servicios y servidores que los proporcionan&quot;, con la arquitectura de 3 capas (Presentación, Negocio, Datos).</li><li><strong>Servicios de integración para aplicaciones:</strong> La Unidad 9 (Comunicación Asíncrona y Fetch API) capacita al estudiante en la implementación de &quot;tecnologías estándar (REST, JSON)&quot; para el ciclo Petición-Respuesta HTTP y el consumo de servicios, promoviendo la interoperabilidad entre sistemas.</li><li><strong>Aplicaciones web interactivas:</strong> Las unidades de Diseño de Interfaz con HTML5/CSS3 (Unidad 6) y Programación del DOM (Unidad 8) forman al estudiante en el &quot;desarrollo de soluciones accesibles desde navegadores, que permiten interacción dinámica con el usuario, conexión con bases de datos y despliegue en entornos de Internet&quot;, utilizando tecnologías como HTML, CSS y JavaScript.</li><li><strong>Aplicaciones multiplataforma:</strong> El Proyecto Final (Unidad 14) exige la integración total del sistema (Frontend + Backend + Base de Datos) desplegado en la nube, ejercitando el &quot;diseño y desarrollo de soluciones que pueden ejecutarse en distintos entornos&quot; y favoreciendo &quot;la portabilidad, la eficiencia en el mantenimiento y la cobertura de usuarios diversos&quot;.</li><li><strong>Modelado y gestión de datos:</strong> La Unidad 11 (Gestión de Bases de Datos Relacionales SQL) aborda directamente el &quot;diseño conceptual, lógico y físico de estructuras de datos&quot; mediante esquemas relacionales, normalización, operaciones CRUD y administración de motores (PostgreSQL/MySQL), garantizando &quot;la integridad, consistencia y eficiencia en el almacenamiento y recuperación de la información&quot;.</li><li><strong>Seguridad y auditoría de aplicaciones:</strong> La Unidad 12 (Integración, Sesiones y Seguridad) incorpora la &quot;autenticación, autorización&quot; y prevención de ataques (Inyecciones SQL, XSS), alineándose con las &quot;prácticas de desarrollo seguro&quot; y los principios de protección de datos que establece esta dimensión.</li></ul><p>De manera secundaria, la propuesta se articula con la línea de <strong>Ingeniería del Software</strong> en las siguientes dimensiones operativas:</p><ul><li><strong>Arquitectura y Diseño de Software:</strong> Las unidades de POO (Unidades 1-5) forman al estudiante en paradigmas de diseño, aplicando &quot;principios de modularidad, desacoplamiento y escalabilidad&quot; que incluyen &quot;arquitecturas monolíticas, orientadas a servicios y basadas en microservicios&quot;.</li><li><strong>Gestión, Calidad y Seguridad del Software:</strong> Complementando la dimensión de seguridad de Desarrollo de Aplicaciones, la línea de Ingeniería del Software aporta el marco de &quot;control de calidad, pruebas automatizadas y prácticas de desarrollo seguro&quot; que se aplica transversalmente en los laboratorios.</li><li><strong>Ingeniería de Datos y Automatización de Procesos:</strong> La Unidad 13 (Docker, VPS, SSH, PM2) introduce al estudiante en &quot;integración continua y automatización de flujos de trabajo&quot;, incluyendo &quot;DevOps, pipelines de despliegue&quot; y contenerización.</li><li><strong>Interfaces y Experiencia de Usuario (UX/UI):</strong> La Unidad 6 (HTML5/CSS3, Flexbox, Grid, Responsive Design) aplica directamente los principios de &quot;usabilidad, accesibilidad, diseño centrado en el usuario y prototipado&quot; que establece esta dimensión.</li></ul><h3 id="continuidad-curricular" tabindex="-1">Continuidad Curricular <a class="header-anchor" href="#continuidad-curricular" aria-label="Permalink to &quot;Continuidad Curricular&quot;">​</a></h3><p>Esta propuesta representa la <strong>continuación natural</strong> de Algorítmica y Programación (Trayecto I), materia inscrita en la línea de Ingeniería del Software. El estudiante transita orgánicamente desde los fundamentos lógico-algorítmicos hacia la construcción de productos tecnológicos reales:</p><ul><li>Los <strong>objetos literales y JSON</strong> aprendidos en Algorítmica se convierten en el formato de intercambio de datos de las APIs REST.</li><li>La <strong>programación modular</strong> del Trayecto I evoluciona hacia el <strong>paradigma de objetos</strong> y la <strong>arquitectura de capas</strong>.</li><li>Las <strong>estructuras de datos</strong> del Trayecto I fundamentan la gestión eficiente de la <strong>persistencia en bases de datos relacionales</strong>.</li></ul><p>Esta continuidad tecnológica (JavaScript/Node.js) elimina la fricción cognitiva del cambio de lenguaje y permite al estudiante concentrarse en los conceptos de alta complejidad propios del Trayecto II.</p><h3 id="fundamentacion-pedagogica" tabindex="-1">Fundamentación Pedagógica <a class="header-anchor" href="#fundamentacion-pedagogica" aria-label="Permalink to &quot;Fundamentación Pedagógica&quot;">​</a></h3><p>En el marco de la transformación curricular del Trayecto II, esta propuesta plantea una transición estratégica del aprendizaje instrumental hacia la Ingeniería de Software como arquitectura integral. Alineada con el Documento Rector del PNFI, esta actualización busca la convergencia de competencias técnicas mediante la unificación del ecosistema de desarrollo.</p><p>El núcleo de la propuesta reside en la reducción de la carga cognitiva mediante la continuidad sintáctica (JavaScript/Node.js). Al eliminar la fragmentación tecnológica característica de modelos anteriores, el estudiante puede dedicar su potencial analítico a la comprensión de conceptos de alta complejidad como la Programación Orientada a Objetos, la arquitectura de tres capas y la seguridad lógica. Este enfoque garantiza la formación de un profesional capaz de liderar proyectos socio-tecnológicos con soluciones escalables, seguras y alineadas con los estándares internacionales de la industria del software.</p><h2 id="diagnostico-de-obsolescencia-y-desafio-pedagogico" tabindex="-1">Diagnóstico de Obsolescencia y Desafío Pedagógico <a class="header-anchor" href="#diagnostico-de-obsolescencia-y-desafio-pedagogico" aria-label="Permalink to &quot;Diagnóstico de Obsolescencia y Desafío Pedagógico&quot;">​</a></h2><p>La revisión del modelo tradicional de Programación II revela factores de obsolescencia que limitan el perfil profesional del egresado y su capacidad de aportar soluciones pertinentes a través de los PST:</p><ul><li><strong>Efecto de la &quot;Caja de Cristal&quot;:</strong> El enfoque anterior limitaba al estudiante al entorno local de su computadora (localhost), impidiendo el contacto con entornos reales de la línea de Desarrollo de Aplicaciones. Nuestra propuesta rompe esta barrera, introduciendo el Despliegue en VPS y Gestión de Procesos (PM2), forzando un encuentro real con el entorno de producción.</li><li><strong>Vulnerabilidad de los Sistemas Monolíticos:</strong> El contenido anterior (basado en scripts lineales) es inadecuado para la web moderna. Esta propuesta introduce el Patrón de Capas y Middlewares como respuesta pedagógica a la necesidad de seguridad, mantenimiento y trabajo colaborativo, competencias exigidas por las dimensiones de Arquitectura y Seguridad de la línea de Ingeniería del Software.</li><li><strong>Invisibilidad de la Seguridad:</strong> En el diseño curricular previo, la seguridad era un tema anecdotórico. En la Propuesta 2026, la Seguridad Lógica (Autenticación, Sesiones y Saneamiento de Datos) es un eje transversal, atendiendo directamente la dimensión de Gestión, Calidad y Seguridad del Software.</li><li><strong>Fricción Cognitiva Tecnológica:</strong> El cambio abrupto a lenguajes como PHP o Java generaba una interrupción en el flujo de aprendizaje y rompía la continuidad con el Trayecto I. Al mantener JavaScript, el estudiante puede enfocar toda su potencia cognitiva en los conceptos complejos de la Orientación a Objetos y Bases de Datos.</li><li><strong>Desarticulación con las Líneas de Investigación:</strong> El contenido anterior no establecía correspondencia con los programas de las líneas de Desarrollo de Aplicaciones ni de Ingeniería del Software. Esta propuesta mapea explícitamente cada bloque temático con las dimensiones operativas correspondientes.</li></ul><hr><h2 id="trimestre-ii-iv-paradigma-de-objetos-e-interfaces-unidades-1-6" tabindex="-1">Trimestre II-IV: Paradigma de Objetos e interfaces (Unidades 1-6) <a class="header-anchor" href="#trimestre-ii-iv-paradigma-de-objetos-e-interfaces-unidades-1-6" aria-label="Permalink to &quot;Trimestre II-IV: Paradigma de Objetos e interfaces (Unidades 1-6)&quot;">​</a></h2><p><strong>Meta:</strong> Migrar de la lógica procedural a la arquitectura de objetos y diseño visual.</p><h3 id="unidad-1-paradigma-de-programacion-orientada-a-objetos" tabindex="-1">Unidad 1: Paradigma de Programación Orientada a Objetos <a class="header-anchor" href="#unidad-1-paradigma-de-programacion-orientada-a-objetos" aria-label="Permalink to &quot;Unidad 1: Paradigma de Programación Orientada a Objetos&quot;">​</a></h3><ul><li>Fundamentos y filosofía del paradigma.</li></ul><h3 id="unidad-2-clases-y-objetos-en-javascript-moderno" tabindex="-1">Unidad 2: Clases y Objetos en JavaScript Moderno <a class="header-anchor" href="#unidad-2-clases-y-objetos-en-javascript-moderno" aria-label="Permalink to &quot;Unidad 2: Clases y Objetos en JavaScript Moderno&quot;">​</a></h3><ul><li>Definición de clases, atributos y métodos.</li><li>Constructores y Especificadores de Acceso (Público/Privado).</li></ul><h3 id="unidad-3-herencia-y-reutilizacion" tabindex="-1">Unidad 3: Herencia y Reutilización <a class="header-anchor" href="#unidad-3-herencia-y-reutilizacion" aria-label="Permalink to &quot;Unidad 3: Herencia y Reutilización&quot;">​</a></h3><ul><li>Extensión de clases, constructores de subclases y superclases.</li></ul><h3 id="unidad-4-polimorfismo-y-abstraccion" tabindex="-1">Unidad 4: Polimorfismo y Abstracción <a class="header-anchor" href="#unidad-4-polimorfismo-y-abstraccion" aria-label="Permalink to &quot;Unidad 4: Polimorfismo y Abstracción&quot;">​</a></h3><ul><li>Sobrecarga y sobreescritura de métodos. Clases abstractas conceptuales.</li></ul><h3 id="unidad-5-interfaces-y-contratos-de-codigo" tabindex="-1">Unidad 5: Interfaces y Contratos de Código <a class="header-anchor" href="#unidad-5-interfaces-y-contratos-de-codigo" aria-label="Permalink to &quot;Unidad 5: Interfaces y Contratos de Código&quot;">​</a></h3><ul><li>Definición de interfaces y su importancia en sistemas escalables.</li></ul><h3 id="unidad-6-herramientas-de-diseno-de-interfaz-frontend" tabindex="-1">Unidad 6: Herramientas de Diseño de Interfaz (Frontend) <a class="header-anchor" href="#unidad-6-herramientas-de-diseno-de-interfaz-frontend" aria-label="Permalink to &quot;Unidad 6: Herramientas de Diseño de Interfaz (Frontend)&quot;">​</a></h3><ul><li>HTML5 Semántico y CSS3 (Flexbox, Grid, Responsive Design).</li></ul><hr><h2 id="trimestre-ii-v-arquitectura-web-y-logica-de-script-unidades-7-10" tabindex="-1">Trimestre II-V: Arquitectura Web y Lógica de Script (Unidades 7-10) <a class="header-anchor" href="#trimestre-ii-v-arquitectura-web-y-logica-de-script-unidades-7-10" aria-label="Permalink to &quot;Trimestre II-V: Arquitectura Web y Lógica de Script (Unidades 7-10)&quot;">​</a></h2><p><strong>Meta:</strong> Construir el puente entre el cliente y el servidor.</p><h3 id="unidad-7-arquitectura-de-sistemas-web" tabindex="-1">Unidad 7: Arquitectura de Sistemas Web <a class="header-anchor" href="#unidad-7-arquitectura-de-sistemas-web" aria-label="Permalink to &quot;Unidad 7: Arquitectura de Sistemas Web&quot;">​</a></h3><ul><li>Modelo Cliente-Servidor y Arquitectura de 3 capas (Presentación, Negocio, Datos).</li></ul><h3 id="unidad-8-programacion-de-script-y-manipulacion-del-dom" tabindex="-1">Unidad 8: Programación de Script y Manipulación del DOM <a class="header-anchor" href="#unidad-8-programacion-de-script-y-manipulacion-del-dom" aria-label="Permalink to &quot;Unidad 8: Programación de Script y Manipulación del DOM&quot;">​</a></h3><ul><li>Interactividad dinámica y gestión de eventos en el navegador.</li><li>Validación de formularios y captura de datos.</li></ul><h3 id="unidad-9-comunicacion-asincrona-y-fetch-api" tabindex="-1">Unidad 9: Comunicación Asíncrona y Fetch API <a class="header-anchor" href="#unidad-9-comunicacion-asincrona-y-fetch-api" aria-label="Permalink to &quot;Unidad 9: Comunicación Asíncrona y Fetch API&quot;">​</a></h3><ul><li>El ciclo Petición-Respuesta (HTTP). Procesamiento de datos JSON.</li><li>Consumo de servicios desde el Frontend.</li></ul><h3 id="unidad-10-servidores-web-con-express-js" tabindex="-1">Unidad 10: Servidores Web con Express.js <a class="header-anchor" href="#unidad-10-servidores-web-con-express-js" aria-label="Permalink to &quot;Unidad 10: Servidores Web con Express.js&quot;">​</a></h3><ul><li>Configuración de servidores profesionales, rutas y middlewares.</li><li>Servicio de archivos estáticos (Arquitectura integrada).</li></ul><hr><h2 id="trimestre-ii-vi-persistencia-seguridad-y-despliegue-unidades-11-14" tabindex="-1">Trimestre II-VI: Persistencia, Seguridad y Despliegue (Unidades 11-14) <a class="header-anchor" href="#trimestre-ii-vi-persistencia-seguridad-y-despliegue-unidades-11-14" aria-label="Permalink to &quot;Trimestre II-VI: Persistencia, Seguridad y Despliegue (Unidades 11-14)&quot;">​</a></h2><p><strong>Meta:</strong> Profesionalización, base de datos y puesta en producción.</p><h3 id="unidad-11-gestion-de-bases-de-datos-relacionales-sql" tabindex="-1">Unidad 11: Gestión de Bases de Datos Relacionales (SQL) <a class="header-anchor" href="#unidad-11-gestion-de-bases-de-datos-relacionales-sql" aria-label="Permalink to &quot;Unidad 11: Gestión de Bases de Datos Relacionales (SQL)&quot;">​</a></h3><ul><li>Administración de motores (PostgreSQL/MySQL), esquemas y backups.</li><li>Operaciones CRUD mediante sentencias SQL optimizadas.</li></ul><h3 id="unidad-12-integracion-sesiones-y-seguridad" tabindex="-1">Unidad 12: Integración, Sesiones y Seguridad <a class="header-anchor" href="#unidad-12-integracion-sesiones-y-seguridad" aria-label="Permalink to &quot;Unidad 12: Integración, Sesiones y Seguridad&quot;">​</a></h3><ul><li>Gestión de Cookies y Sesiones para autenticación de usuarios.</li><li>Protección de rutas y prevención de ataques (Inyecciones SQL/XSS).</li></ul><h3 id="unidad-13-herramientas-de-servidor-y-produccion" tabindex="-1">Unidad 13: Herramientas de Servidor y Producción <a class="header-anchor" href="#unidad-13-herramientas-de-servidor-y-produccion" aria-label="Permalink to &quot;Unidad 13: Herramientas de Servidor y Producción&quot;">​</a></h3><ul><li>Virtualización con Docker: Creación de imágenes y contenedores para entornos reproducibles.</li><li>Configuración de entornos reales (VPS) mediante SSH.</li><li>Gestión de procesos con PM2 y despliegue continuo.</li></ul><h3 id="unidad-14-proyecto-final-de-carrera-defensa" tabindex="-1">Unidad 14: Proyecto Final de Carrera (Defensa) <a class="header-anchor" href="#unidad-14-proyecto-final-de-carrera-defensa" aria-label="Permalink to &quot;Unidad 14: Proyecto Final de Carrera (Defensa)&quot;">​</a></h3><ul><li>Integración total del sistema: Frontend + Backend + BD en la nube.</li></ul><hr><h2 id="estrategias-pedagogicas" tabindex="-1">Estrategias Pedagógicas <a class="header-anchor" href="#estrategias-pedagogicas" aria-label="Permalink to &quot;Estrategias Pedagógicas&quot;">​</a></h2><p>Las estrategias responden a los principios del &quot;aprender haciendo&quot; promovidos por el Documento Rector del PNFI y se articulan con las dimensiones operativas de las líneas de Desarrollo de Aplicaciones e Ingeniería del Software:</p><ul><li><strong>Metodología &quot;Learning by Doing&quot; (Aprender Haciendo):</strong> Desarrollo de micro-proyectos semanales que escalan hasta convertirse en el proyecto final. Cada micro-proyecto se vincula con un programa específico de la línea de Desarrollo de Aplicaciones (ej: un CRUD = Servicios de integración para aplicaciones; un Login = Aplicaciones web interactivas).</li><li><strong>Sesiones de Live Coding:</strong> El docente desarrolla módulos de software en tiempo real, permitiendo al alumno observar el proceso de debugging y resolución de problemas en entornos profesionales.</li><li><strong>Revisión de Pares (Code Review):</strong> Uso de Git para que los alumnos revisen el código de sus compañeros, fomentando la lectura de código ajeno y las mejores prácticas de la dimensión de Gestión, Calidad y Seguridad del Software.</li><li><strong>Arquitectura de 3 Capas:</strong> Aplicación obligatoria de la separación de responsabilidades en todos los laboratorios desde el segundo trimestre, alineándose con el programa de Aplicaciones cliente-servidor.</li></ul><h2 id="recursos-e-herramientas-tecnologicas" tabindex="-1">Recursos e Herramientas Tecnológicas <a class="header-anchor" href="#recursos-e-herramientas-tecnologicas" aria-label="Permalink to &quot;Recursos e Herramientas Tecnológicas&quot;">​</a></h2><p>El entorno de aprendizaje simula una estación de trabajo de ingeniería de software real, utilizando herramientas alineadas con los programas de la línea de Desarrollo de Aplicaciones:</p><ul><li><strong>Software Base:</strong> Visual Studio Code (Extensiones Pro), Node.js (LTS), Git — continuidad con el ecosistema del Trayecto I.</li><li><strong>Ecosistema Backend:</strong> Express.js, NPM (Gestión de dependencias) — programa de Aplicaciones cliente-servidor.</li><li><strong>Gestión de Datos:</strong> PostgreSQL / MySQL, Clientes de DB (DBeaver/TablePlus) — programas de Servicios de integración para aplicaciones y Modelado y gestión de datos.</li><li><strong>Pruebas de API:</strong> Postman o Insomnia para la verificación de servicios web — programa de Servicios de integración para aplicaciones.</li><li><strong>Infraestructura:</strong> Docker &amp; Docker Compose (Contenerización), Servidores VPS, SSH y PM2 — dimensión de Ingeniería de Datos y Automatización de Procesos de la línea de Ingeniería del Software.</li><li><strong>Material Educativo:</strong> Repositorios de GitHub con plantillas base y documentación en Markdown.</li></ul><h2 id="sistema-de-evaluacion" tabindex="-1">Sistema de Evaluación <a class="header-anchor" href="#sistema-de-evaluacion" aria-label="Permalink to &quot;Sistema de Evaluación&quot;">​</a></h2><p>La evaluación es continua y orientada a validar las competencias asociadas a los programas de la línea de Desarrollo de Aplicaciones y las dimensiones de Ingeniería del Software:</p><ul><li><strong>Evaluación Formativa:</strong> Retroalimentación constante sobre la calidad del código, aplicación de Clean Code y patrones de diseño (dimensión de Gestión, Calidad y Seguridad del Software).</li><li><strong>Evaluación Sumativa (4 Cortes por Trimestre):</strong><ul><li><strong>Laboratorios Técnicos (50%):</strong> Implementación de funcionalidades específicas (ej: un CRUD, un Login). Evalúa competencias de Aplicaciones cliente-servidor y Servicios de integración para aplicaciones.</li><li><strong>Exámenes de Lógica/Arquitectura (25%):</strong> Validación de conceptos teóricos y diseño de esquemas de datos. Evalúa competencias de Arquitectura y Diseño de Software, y Modelado y gestión de datos.</li><li><strong>Proyecto Final (25%):</strong> Prototipo Totalmente Funcional de un sistema integral Full-Stack, desplegado en un servidor real (VPS) y validado mediante casos de uso reales. Evalúa la integración de todas las dimensiones: Aplicaciones multiplataforma + Seguridad y auditoría de aplicaciones + Ingeniería de Datos y Automatización de Procesos.</li></ul></li></ul><h2 id="referencias-bibliograficas" tabindex="-1">Referencias Bibliográficas <a class="header-anchor" href="#referencias-bibliograficas" aria-label="Permalink to &quot;Referencias Bibliográficas&quot;">​</a></h2><ul><li>Martin, R. C. (2008). <em>Clean Code: A Handbook of Agile Software Craftsmanship</em>. Prentice Hall.</li><li>Gamma, E., et al. (1994). <em>Design Patterns: Elements of Reusable Object-Oriented Software</em>. Addison-Wesley.</li><li>Flanagan, D. (2020). <em>JavaScript: The Definitive Guide</em>. O&#39;Reilly Media.</li><li>Ministerio del Poder Popular para la Educación Universitaria. <em>Documento Rector del PNFI</em>. Caracas, Venezuela.</li><li>Ministerio del Poder Popular para la Educación Universitaria. <em>Líneas de Investigación del PNFI: Actualización 2024</em>. Caracas, Venezuela.</li><li>Mozilla Developer Network (MDN). <em>HTTP and Express.js Documentation</em>. <a href="https://expressjs.com/" target="_blank" rel="noreferrer">https://expressjs.com/</a></li><li>Ley de Infogobierno (2013). <em>Gaceta Oficial de la República Bolivariana de Venezuela</em>. <a href="https://www.conati.gob.ve/" target="_blank" rel="noreferrer">https://www.conati.gob.ve/</a></li><li>ISO/IEC 25010:2011. <em>Systems and software engineering — Systems and software Quality Requirements and Evaluation (SQuaRE)</em>.</li><li>Fielding, R. T. (2000). <em>Architectural Styles and the Design of Network-based Software Architectures</em>. Doctoral Dissertation, University of California, Irvine.</li></ul>',72)])])}const m=a(r,[["render",s]]);export{g as __pageData,m as default};
